package com.yam.funds.infrastructure.out.persistence.mongo;

import com.yam.funds.domain.model.ClientId;
import com.yam.funds.domain.model.SubscriptionId;
import com.yam.funds.domain.model.TransactionId;
import com.yam.funds.domain.port.out.IdentifierGeneratorPort;
import org.springframework.stereotype.Component;

/**
 * Assigns identifiers from a random UUID source.
 *
 * <p>Generated by the application rather than by the database, so an aggregate carries
 * its identity before it is ever persisted — which is what lets a use case build a
 * client, its subscription and the resulting ledger entry as one consistent unit.
 */
@Component
public class UuidIdentifierGeneratorAdapter implements IdentifierGeneratorPort {

    @Override
    public ClientId nextClientId() {
        return ClientId.generate();
    }

    @Override
    public SubscriptionId nextSubscriptionId() {
        return SubscriptionId.generate();
    }

    @Override
    public TransactionId nextTransactionId() {
        return TransactionId.generate();
    }
}
